1	import { copyFileSync, mkdirSync, rmSync, readFileSync, writeFileSync, existsSync, realpathSync } from 'node:fs';
2	import { execFileSync } from 'node:child_process';
3	import { join, dirname } from 'node:path';
4	import { fileURLToPath, pathToFileURL } from 'node:url';
5	import { discoverPacks } from '../packs/registry.mjs';
6	import { computeVendorSet, SHARED_SUBDIR } from './vendor.mjs';
7	
8	// The vendor WRITER (mount/DESIGN.md): converge a consumer's .claudinite/shared/
9	// to this canon tree's vendor set and advance the stamp — the local half of the
10	// transactional update. Callers: the adoption flow and an on-demand refresh run
11	// it from a freshly fetched canon tree against the consumer checkout; the
12	// nightly's fleet integration performs the equivalent writes over the API.
13	// Convergence is unconditional and whole-set: shared/ is rebuilt from the set
14	// (stale files vanish, local edits revert), .claudinite/local_packs/ and
15	// everything else in the consumer is untouched. Errors abort BEFORE any write —
16	// the repo keeps running its old snapshot (the transactional contract).
17	//
18	// Convergence is direction-blind (copy-if-different), so a canon checkout behind
19	// main would silently REWIND the member's whole corpus and stamp it newer (#328).
20	// Two guards refuse that before any write, when the canon root carries git
21	// metadata: a passed --ref must equal the checkout's HEAD, and the member's
22	// previously stamped ref must be an ancestor of it. A rootless canon tree
23	// (bootstrap's fetched snapshot — no .git) skips both: it is head by
24	// construction and carries no history to check ancestry against.
25	const canonRoot = dirname(dirname(fileURLToPath(import.meta.url)));
26	
27	// All git use is LOCAL introspection of the canon checkout (rev-parse,
28	// merge-base read the object db — no network, no credential); the remote-head
29	// comparison the guards can't make locally is the worker's, over MCP. Git
30	// discovers .git by walking UP, and a VENDORED copy of this file runs inside
31	// the consumer's own repo (.claudinite/shared/mount/) — where git would answer
32	// with the CONSUMER's HEAD — so only a checkout whose toplevel is the canon
33	// root itself speaks for the canon; anything else is treated as rootless.
34	const git = (...args) => execFileSync('git', args, { cwd: canonRoot, stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim();
35	const gitHead = () => {
36	  try {
37	    if (realpathSync(git('rev-parse', '--show-toplevel')) !== realpathSync(canonRoot)) return null;
38	    return git('rev-parse', 'HEAD');
39	  } catch { return null; }
40	};
41	const isAncestorOfHead = (sha) => { try { git('merge-base', '--is-ancestor', sha, 'HEAD'); return true; } catch { return false; } };
42	
43	export async function applyVendor(targetRoot, { ref = null } = {}) {
44	  const settingsPath = join(targetRoot, '.claudinite-checks.json');
45	  if (!existsSync(settingsPath)) {
46	    return { errors: [{ what: `${targetRoot} has no .claudinite-checks.json`, fix: 'write the pack declaration first (adoption seeds it)' }] };
47	  }
48	  let raw;
49	  try {
50	    raw = JSON.parse(readFileSync(settingsPath, 'utf8'));
51	  } catch (e) {
52	    return { errors: [{ what: `.claudinite-checks.json is not valid JSON: ${e.message}`, fix: 'fix the JSON syntax, then rerun' }] };
53	  }
54	  const declared = Array.isArray(raw.packs) ? raw.packs : [];
55	
56	  const head = gitHead();
57	  if (head) {
58	    if (ref && ref !== head) {
59	      return { errors: [{ what: `--ref ${ref} does not match this canon checkout's HEAD (${head})`, fix: 'sync the checkout to the verified remote head (git fetch && git merge --ff-only), then rerun with that head as --ref' }] };
60	    }
61	    ref = ref ?? head; // stamp provenance even when the caller passed none
62	    const prior = raw.claudinite?.ref;
63	    if (prior && !isAncestorOfHead(prior)) {
64	      return { errors: [{ what: `the target's stamped ref (${prior}) is not an ancestor of this checkout's HEAD (${head}) — converging would rewind the member (#328)`, fix: 'sync the canon checkout to the remote head (git fetch && git merge --ff-only; ensure full history), then rerun' }] };
65	    }
66	  }
67	
68	  // Skills the canon can't derive: ones the consumer's own local packs require.
69	  // Only canon-resident names count — a local pack's bundled skills live in the
70	  // consumer's tree and are never vendored.
71	  const local = (await discoverPacks({ localRoot: targetRoot })).packs.filter((p) => p.local);
72	  const extraSkills = [...new Set(local.flatMap((p) => p.skills ?? []))]
73	    .filter((name) => existsSync(join(canonRoot, 'skills', name)));
74	
75	  const { files, errors } = await computeVendorSet(declared, { extraSkills });
76	  if (errors.length) return { errors };
77	
78	  const sharedDir = join(targetRoot, SHARED_SUBDIR);
79	  rmSync(sharedDir, { recursive: true, force: true });
80	  for (const file of files) {
81	    const dest = join(sharedDir, file);
82	    mkdirSync(dirname(dest), { recursive: true });
83	    copyFileSync(join(canonRoot, file), dest);
84	  }
85	
86	  // Full ISO datetime, not a bare date: note selection is same-day-INCLUSIVE
87	  // against the stamp's day (a note landing later on the stamp's day must still
88	  // apply — #330), and the datetime pins exactly when this snapshot was taken.
89	  raw.claudinite = { updated: new Date().toISOString(), ...(ref ? { ref } : {}) };
90	  writeFileSync(settingsPath, JSON.stringify(raw, null, 2) + '\n');
91	  return { files: files.length, stamp: raw.claudinite, errors: [] };
92	}
93	
94	// CLI: node <canon>/mount/apply-vendor.mjs [--target <consumer-root>] [--ref <sha>]
95	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
96	  const args = process.argv.slice(2);
97	  const opt = (name) => {
98	    const i = args.indexOf(name);
99	    return i >= 0 ? args[i + 1] : undefined;
100	  };
101	  const result = await applyVendor(opt('--target') ?? process.cwd(), { ref: opt('--ref') ?? null });
102	  if (result.errors.length) {
103	    for (const e of result.errors) console.error(`ERROR: ${e.what}\n  fix: ${e.fix}`);
104	    process.exit(1);
105	  }
106	  console.log(`vendored ${result.files} files into ${SHARED_SUBDIR}; stamp ${JSON.stringify(result.stamp)}`);
107	}
108

