import noEnforcementNarration from './no-enforcement-narration.mjs';

// The check-the-work rules validating this skill's action — authoring a skill
// in the Claudinite corpus. Discovered by skills/registry.mjs, run at every
// Stop and in CI; inert outside the canon home repo.
export default [noEnforcementNarration];
import { dirname } from 'node:path';
import { finding } from '../../checks/lib/findings.mjs';
import { matchingLines, ruleIdsIn } from '../../checks/lib/lines.mjs';

