218	  const entryById = new Map();
219	  for (const entry of declared) {
220	    const id = packEntryId(entry);
221	    if (id !== undefined && !entryById.has(id)) entryById.set(id, entry);
222	  }
223	  const orderedIds = [];
224	  const seen = new Set();
225	  const visit = (id) => {
226	    if (seen.has(id)) return;
227	    if (!declaredIds.has(id) && !byId.has(id)) return; // don't materialize a phantom dep
228	    seen.add(id);
229	    orderedIds.push(id);
230	    for (const dep of byId.get(id)?.requires ?? []) visit(dep);
231	  };
232	  for (const entry of declared) {
233	    const id = packEntryId(entry);
234	    if (id !== undefined) visit(id);
235	  }
236	  const via = (id) => orderedIds.filter((p) => byId.get(p)?.requires?.includes(id)).sort();
237	  const resolved = orderedIds.map((id) => {
238	    const entry = entryById.get(id);
239	    if (entry === undefined) return { id, via: via(id) };
240	    if (typeof entry === 'object' && 'via' in entry) return { ...entry, via: via(id) };
241	    return entry;
242	  });
243	  return [...resolved, ...declared.filter((entry) => packEntryId(entry) === undefined)];
244	}
