  const st = lstatOrNull(join(mountDir, entry));
  if (!st || !st.isSymbolicLink()) return false;
  const target = resolve(mountDir, readlinkSync(join(mountDir, entry)));
  return ownedRoots.some((r) => target.startsWith(r + sep));
};

