9	// This test lives at <repo>/mount/session-start.test.mjs.
10	const MOUNT_DIR = dirname(fileURLToPath(import.meta.url));
11	
12	// A hermetic corpus mirroring the real layout: the REAL mount/session-start.sh
13	// (it self-locates via BASH_SOURCE and resolves the mount-local prefs step
14	// beside itself, the rest one level up at the corpus root) plus tiny STUB
15	// steps, so the test exercises the ORCHESTRATOR's own contract — sequence,
16	// stdout forwarding, lifecycle logging, exit 0 — without dragging in the real
17	// children and their dependencies.
18	function makeCorpus({ prefs = '#!/bin/bash\n', prose = '', skills = '', env = '', interview = '' } = {}) {
19	  const root = mkdtempSync(join(tmpdir(), 'claudinite-sessionstart-'));
20	  mkdirSync(join(root, 'mount'), { recursive: true });
21	  copyFileSync(join(MOUNT_DIR, 'session-start.sh'), join(root, 'mount', 'session-start.sh'));
22	  mkdirSync(join(root, 'packs'), { recursive: true });
23	  mkdirSync(join(root, 'skills'), { recursive: true });
24	  writeFileSync(join(root, 'mount', 'inject-preferences.sh'), prefs);
25	  writeFileSync(join(root, 'packs', 'load-active-prose.mjs'), prose);
26	  writeFileSync(join(root, 'skills', 'mount-skills.mjs'), skills);
27	  writeFileSync(join(root, 'packs', 'env.mjs'), env);
28	  writeFileSync(join(root, 'packs', 'interview.mjs'), interview);
29	  return root;
30	}
31	
32	function run(corpus, projectDir, env = {}) {
33	  return spawnSync('bash', [join(corpus, 'mount', 'session-start.sh')], {
34	    encoding: 'utf8',
35	    env: { ...process.env, CLAUDE_PROJECT_DIR: projectDir, CLAUDINITE_HOOK_RUN: 'testrun', ...env },
36	  });
37	}
38	
39	test('orchestrator runs steps in order, forwards only step stdout, logs the lifecycle, exits 0', () => {
40	  const corpus = makeCorpus({
41	    prefs: '#!/bin/bash\necho PREFS\n',
42	    prose: 'process.stdout.write("PROSE\\n");',
43	  });
44	  const projectDir = mkdtempSync(join(tmpdir(), 'claudinite-proj-'));
45	  const r = run(corpus, projectDir);
46	  assert.equal(r.status, 0);
47	  // Only the steps' stdout reaches the hook's stdout (→ session context), in
48	  // order, followed by the one-line confirmation footer; the timestamped log
49	  // goes to stderr + the file, never stdout.
50	  assert.ok(r.stdout.startsWith('PREFS\nPROSE\n'), r.stdout);
51	  assert.match(r.stdout, /^Claudinite session-start: ran 5 steps \(inject-preferences, load-active-prose, mount-skills, env-check, interview-check\) at .+\.$/m);
52	  assert.doesNotMatch(r.stdout, /WARNING/); // all steps exited 0
