    'packs/basics/skills/newskill/SKILL.md': '---\nname: newskill\n---\nbody\n',
    '.claudinite/local_packs/curate/skills/homeskill/SKILL.md': '---\nname: homeskill\n---\nbody\n',
  } });
  try {
    const findings = run(catalogCompleteness, root, 'all');
