1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { mkdtempSync, mkdirSync, writeFileSync, copyFileSync } from 'node:fs';
4	import { tmpdir } from 'node:os';
5	import { join, dirname } from 'node:path';
6	import { fileURLToPath, pathToFileURL } from 'node:url';
7	
8	// This test lives at <repo>/mount/vendor.test.mjs.
9	const MOUNT_DIR = dirname(fileURLToPath(import.meta.url));
10	const REPO_ROOT = dirname(MOUNT_DIR);
11	
12	function writeAt(root, rel, content) {
13	  mkdirSync(dirname(join(root, rel)), { recursive: true });
14	  writeFileSync(join(root, rel), content);
15	}
16	
17	// A hermetic canon mirroring the real layout: the REAL vendor.mjs with the
18	// REAL modules it imports (packs/registry.mjs, checks/lib/imports.mjs — all
19	// self-locate relative to their own file), a small engine tree with the things
20	// that must be EXCLUDED present (tests, engine-root docs, preferences), and
21	// fixture packs/skills — so the tests exercise the structural-discovery
22	// contract, not the live corpus's contents.
23	function makeCanon({ packs = [], skills = [] } = {}) {
24	  const root = mkdtempSync(join(tmpdir(), 'claudinite-vendor-'));
25	  mkdirSync(join(root, 'mount'), { recursive: true });
26	  mkdirSync(join(root, 'packs'), { recursive: true });
27	  mkdirSync(join(root, 'checks', 'lib'), { recursive: true });
28	  copyFileSync(join(MOUNT_DIR, 'vendor.mjs'), join(root, 'mount', 'vendor.mjs'));
29	  copyFileSync(join(REPO_ROOT, 'packs', 'registry.mjs'), join(root, 'packs', 'registry.mjs'));
30	  copyFileSync(join(REPO_ROOT, 'checks', 'lib', 'imports.mjs'), join(root, 'checks', 'lib', 'imports.mjs'));
31	  writeAt(root, 'CLAUDE.md', 'index\n');
32	  // engine roots: real-shaped content plus everything that must stay out
33	  writeAt(root, 'checks/run.mjs', 'stub\n');
34	  writeAt(root, 'checks/lib/context.mjs', 'stub\n');
35	  writeAt(root, 'checks/README.md', 'canon doc\n');
36	  writeAt(root, 'checks/test/runner.test.mjs', 'stub\n');
37	  writeAt(root, 'mount/session-start.sh', 'stub\n');
38	  writeAt(root, 'mount/DESIGN.md', 'canon doc\n');
39	  // machinery roots: top-level .mjs picked up, tests and dirs' docs not
40	  writeAt(root, 'packs/load-active-prose.mjs', 'stub\n');
41	  writeAt(root, 'packs/env.mjs', 'stub\n');
