  execFileSync('git', ['checkout', '-q', c1], { cwd: canon }); // a stale checkout
  const target = makeTarget({ packs: ['alpha'], claudinite: { updated: '2026-01-01T00:00:00Z', ref: c2 } });
  const r = await applyAt(canon, target);
