def repair(pattern_root, max_up):
    too_long = re.compile(r'(?:\.\./){%d,}' % (max_up + 1))
    for path in glob.glob(pattern_root, recursive=True):
        if not os.path.isfile(path): continue
        try: s = open(path, encoding='utf-8').read()
        except Exception: continue
        def fix(m):
            n = m.group(0).count('../')
            return '../' * (n - 2)
        new = too_long.sub(fix, s)
        if new != s:
            open(path, 'w', encoding='utf-8').write(new)
