1	#!/usr/bin/env node
2	// Claudinite conformance-check runner (see DESIGN.md). Dependency-free Node ≥18.
3	//   (default)   whole-repo sweep — milliseconds on a text corpus, sees cross-file breakage
4	//   --changed   transitional: scope to files changed vs the merge-base with main
5	//               (adopting a repo with a backlog only — not the enforcement default)
6	//   --base REF  override the base ref
7	//   --list      machine-readable rule catalog (id, severity, description, doc)
8	//   --init      write .claudinite-checks.json — basics plus the fingerprinted packs
9	import { writeFileSync, existsSync } from 'node:fs';
10	import { join } from 'node:path';
11	import { fileURLToPath } from 'node:url';
12	import { buildContext, loadConfig } from './checks_helpers/context.mjs';
13	import { applyConfig, render } from './checks_helpers/findings.mjs';
14	import { discoverPacks, isActive, resolveDeclaredPacks } from './pack_loader/registry.mjs';
15	
16	// The adoption-interview machinery is the adopt-claudinite skill's, bundled in
17	// the baseline pack (packs/basics/skills/adopt-claudinite/). A consumer that
18	// doesn't declare basics doesn't vendor it — no adoption skill, no interview —
19	// so resolve it fail-soft: absent file, inert interview.
20	const interviewUrl = new URL('../packs/basics/skills/adopt-claudinite/interview.mjs', import.meta.url);
21	const { interviewState } = existsSync(fileURLToPath(interviewUrl))
22	  ? await import(interviewUrl.href)
23	  : { interviewState: () => ({ pending: [], stale: [], errors: [] }) };
24	
25	const args = process.argv.slice(2);
26	const has = (flag) => args.includes(flag);
27	const value = (flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
28	const root = value('--root') || process.cwd();
29	
30	// Canon packs plus the repo's own local packs (.claudinite/local_packs/). A
31	// broken/duplicate manifest doesn't sink the run — it comes back in `packErrors`
32	// and is surfaced as a blocking config finding, so the Stop hook shows a
33	// diagnostic instead of silently dropping the pack's checks.
34	const { packs, errors: packErrors } = await discoverPacks({ localRoot: root });
35	
36	// A pack's contributedRules seam: the pack interprets the contributions other
37	// packs address to it on their manifests (`contributes`), returning
38	// first-class rules — how packs compose through declaration + configuration
39	// instead of importing each other's code. Isolated per pack, like manifest
40	// loading: one broken seam (a consumer-authored local pack's, say) must not
41	// sink the run.
42	const contributedRules = (pack, fromPacks, onError) => {
43	  try { return pack.contributedRules?.(fromPacks) ?? []; }
44	  catch (e) { onError?.(e); return []; }
45	};
46	
47	if (has('--list')) {
48	  const rules = [
49	    ...packs.flatMap((p) => p.rules ?? []),
50	    ...packs.flatMap((p) => p.skillChecks ?? []),
51	    ...packs.flatMap((p) => contributedRules(p, packs)),
52	  ];
53	  for (const r of rules.sort((a, b) => a.id.localeCompare(b.id))) {
54	    console.log(`${r.id}\t${r.severity}\t${r.description}\t${r.doc}`);
55	  }
56	  process.exit(0);
57	}
58	
59	if (has('--init')) {
60	  const path = join(root, '.claudinite-checks.json');
61	  if (existsSync(path)) {
62	    console.log(`${path} already exists — leaving it as-is.`);
63	    process.exit(0);
64	  }
65	  const ctx = buildContext({ root, mode: 'all' });
66	  // No pack is active by default, so the baseline is seeded as an explicit
67	  // declaration alongside the fingerprinted packs: every pack that flags
68	  // `seededByDefault` is written in (discovered structurally — the engine names
69	  // no pack), plus the ones a fingerprint detects. A seeded pack is still
70	  // opt-out-able where its own policy allows (baselining re-adds only the packs
71	  // whose absence it treats as drift), so removing a seeded declaration can
72	  // stick; each seeded pack ships its own one-time seed migration for the fleet.
73	  // Local packs are declared by hand, never fingerprinted or seeded — exclude
74	  // them from --init's seeding so a repo that already carries local packs (but
75	  // no config yet) doesn't auto-declare them.
76	  const seeded = packs.filter((p) => p.seededByDefault && !p.local).map((p) => p.id);
77	  const detected = [...seeded, ...packs.filter((p) => p.detect && !p.local && p.detect(ctx)).map((p) => p.id)];
78	  // A pack can't be imported without its dependencies — pull each declared pack's
79	  // `requires` closure into the declaration so it's complete and visible.
80	  const declared = resolveDeclaredPacks(detected, packs);
81	  // maintenance.delivery is deliberately materialized, not defaulted — the selection
82	  // must be visible in the file where a project would change it (see engine/README.md).
83	  // Only what carries a decision: the declaration and the always-explicit
84	  // delivery. Empty rules/accept boilerplate is noise, not settings (#385);
85	  // loadConfig defaults absent keys.
86	  writeFileSync(path, `${JSON.stringify({ packs: declared, maintenance: { delivery: 'auto-merge' } }, null, 2)}\n`);
87	  console.log(`Wrote ${path} (packs: ${declared.join(', ')}).`);
88	  // Adoption interviews, strict at bootstrap: the flow that runs --init has the
89	  // owner present, so surface every declared pack's questions for the adoption
90	  // interview NOW (bootstrap.md Part 6). Outside bootstrap the same gap only
91	  // ever surfaces as a mild SessionStart note (packs/basics/skills/adopt-claudinite/interview.mjs).
92	  const { pending } = interviewState(packs, loadConfig(root));
93	  if (pending.length) {
94	    console.log('\nAdoption questions pending — interview the owner as part of this adoption: ask each'
95	      + ' question, record the answer verbatim on the pack\'s entry as answers.<question-id>, and'
96	      + ' derive the entry\'s config where the question\'s distill note says how.');
97	    for (const p of pending) for (const q of p.questions) console.log(`  ${p.packId} / ${q.id}: ${q.prompt}`);
98	  }
99	  process.exit(0);
100	}
101	
102	const mode = has('--changed') ? 'changed' : 'all';
103	// --transcript: the session transcript the Stop hook forwards, enabling the
104	// conversation-surface rules; absent everywhere else (CI), where they self-skip.
105	const ctx = buildContext({ root, mode, baseOverride: value('--base'), transcriptPath: value('--transcript') });
106	
107	const configError = (what, fix) => ({
108	  rule: 'config', severity: 'blocking', file: '.claudinite-checks.json', line: null,
109	  what, why: 'the settings file is what executes — a bad key, value, or pack name silently changes what runs', fix, doc: 'engine/README.md',
110	});
111	
112	let findings = [];
113	// Settings validity, checked at load: malformed JSON, an unknown property, and a
114	// wrong pack name are all equally settings errors. loadConfig reports the first
115	// two; the runner adds unknown pack names here because only it holds the registry.
116	for (const e of ctx.config.errors) findings.push(configError(e.what, e.fix));
117	// A broken/duplicate local pack.mjs is a config-level fault too — surface it with
118	// a diagnostic instead of silently omitting the pack (and its checks).
119	for (const e of packErrors) findings.push(configError(e.what, e.fix));
120	// knownIds spans canon AND local packs, so a declared local pack id is valid and
121	// the unknown-pack message lists it among the declarable packs. ctx.config.packs
122	// is loadConfig's normalized view — bare ids, a namespaced local_packs/<name>
123	// declaration already resolved through packEntryId — so the membership test here
124	// compares bare id to bare id whichever form the file used.
125	const knownIds = new Set(packs.map((p) => p.id));
126	for (const name of ctx.config.packs) {
127	  if (typeof name === 'string' && !knownIds.has(name)) {
128	    findings.push(configError(`declares unknown pack "${name}"`, `remove it or fix the name — declarable packs: ${[...knownIds].sort().join(', ')}`));
129	  }
130	}
