1	import { readdirSync, readFileSync, existsSync } from 'node:fs';
2	import { join, dirname } from 'node:path';
3	import { fileURLToPath } from 'node:url';
4	import { loadPacks, resolveDeclaredPacks, packEntryId, SHARED_SUBDIR } from '../pack_loader/registry.mjs';
5	import { relativeImports, resolveRelative, ENGINE_DIR_ROOTS } from '../checks_helpers/imports.mjs';
6	
7	// The vendor-set computation for the vendored mount (DESIGN.md): given a repo's
8	// pack declaration, the minimal corpus file set that repo persists under
9	// SHARED_SUBDIR — canon-relative paths, mirroring exactly what a future
10	// submodule mounted at that same root would place there. Always computed
11	// against the canon tree THIS module ships in — the nightly runs it from the
12	// home checkout, an on-demand refresh from the tree it just fetched — so the
13	// set and the content can never come from different snapshots.
14	const canonRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url)))); // <canon>/engine/mount/
15	
16	// Re-exported for the writers (the nightly update pass, an on-demand refresh):
17	// the consumer-side root the set materializes under.
18	export { SHARED_SUBDIR };
19	
20	// The engine is discovered structurally, never listed file-by-file: the engine
21	// root vendors wholesale (a new engine file ships with no edit here). The list
22	// lives in the engine lib (engine/checks_helpers/imports.mjs) — the same
23	// surface the pack-independence barrier confines pack imports to, so "what a
24	// pack may import" and "what every consumer carries" can never drift apart —
25	// re-exported here as the vendor-set contract (DESIGN.md). Excluded within the
26	// engine root: tests (*.test.mjs and test/ directories) and *.md — engine docs
27	// are canon-maintainer reference, read upstream when needed, while a pack's
28	// .md files are the payload and ride its directory below.
29	export { ENGINE_DIR_ROOTS };
30	
31	const isTest = (name) => name.endsWith('.test.mjs');
32	
33	function walk(relDir, files, errors, { engine = false } = {}) {
34	  let entries;
35	  try {
36	    entries = readdirSync(join(canonRoot, relDir), { withFileTypes: true });
37	  } catch (e) {
38	    errors.push({
39	      what: `${relDir} is not a readable directory in the canon tree: ${e.message}`,
40	      fix: `restore ${relDir}, or fix what names it (an engine root, a pack.mjs skills list)`,
41	    });
42	    return;
43	  }
44	  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
45	    if (entry.isDirectory()) {
46	      if (engine && entry.name === 'test') continue;
47	      walk(`${relDir}/${entry.name}`, files, errors, { engine });
48	    } else if (!isTest(entry.name) && !(engine && entry.name.endsWith('.md'))) {
49	      files.add(`${relDir}/${entry.name}`);
50	    }
51	  }
52	}
53	
54	// declaredEntries: the raw `packs` array from .claudinite-checks.json (id
55	// strings and/or entry objects). Returns { files, errors }:
56	// sorted canon-relative paths, and { what, fix } diagnostics. Ids naming no
57	// canon pack (a consumer's local packs, or a typo the runner's settings
58	// validation already flags) are skipped without error; per-user preferences
59	// are deliberately absent — they are never vendored (DESIGN.md). A pack's
60	// bundled skills (<pack>/skills/) ride its directory walk — there is no
61	// separate skills collection to union (#385).
62	export async function computeVendorSet(declaredEntries) {
63	  const files = new Set();
64	  const errors = [];
65	
66	  for (const root of ENGINE_DIR_ROOTS) walk(root, files, errors, { engine: true });
67	
68	  const packs = await loadPacks();
69	  const byId = new Map(packs.map((p) => [p.id, p]));
70	  const ids = [];
71	  for (const entry of resolveDeclaredPacks(declaredEntries ?? [], packs)) {
72	    const id = packEntryId(entry);
73	    if (id !== undefined && byId.has(id) && !ids.includes(id)) ids.push(id);
74	  }
75	  for (const id of ids) walk(`packs/${id}`, files, errors);
76	
77	  // Coherence guard: the set must be import-closed — every relative import in
78	  // every .mjs it carries resolves to a file it also carries. Structural
79	  // discovery plus the requires closure make that true by construction while
80	  // the corpus honors pack-independence (a pack imports only its own files and
81	  // the engine surface, both always in the set); a violation is canon-side
82	  // breakage, reported here so convergence aborts BEFORE any write (the
83	  // transactional contract) instead of the flipped member crashing on a
84	  // missing module — the failure the gated flip's pilot abort surfaced.
85	  const inSet = new Set(files);
86	  for (const file of inSet) {
87	    if (!file.endsWith('.mjs')) continue;
88	    let src;
89	    try { src = readFileSync(join(canonRoot, file), 'utf8'); } catch { continue; }
90	    for (const { spec } of relativeImports(src)) {
91	      const resolved = resolveRelative(file, spec, (p) => existsSync(join(canonRoot, p)));
92	      if (!resolved) {
93	        errors.push({
94	          what: `${file} imports "${spec}", which resolves to no file in the canon tree`,
95	          fix: 'fix the import specifier, or restore the file it names',
96	        });
97	      } else if (!inSet.has(resolved)) {
98	        errors.push({
99	          what: `${file} imports "${spec}" → ${resolved}, which the vendor set does not carry — a pack imports only its own files and the engine surface (pack-independence)`,
100	          fix: 'fix the import to honor pack-independence (declare the dependency and contribute configuration, or move the helper into checks/lib)',
101	        });
102	      }
103	    }
104	  }
105	
106	  return { files: [...files].sort(), errors };
107	}

